#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
ftp_publish.py - идемпотентный FTP-деплой статьи-гайда (мост website→FTP, publish_target=ftp).

Портируемый инструмент: креды и домен живут в ~/.config/seo-publish.json (тот же конфиг,
что у _shared/tools/seo_publish.py). Персональных данных в коде нет.

CAS (compare-and-swap) - обязательный шаг ПЕРЕД любой заливкой каталога статьи.
Порядок работы над страницей теперь такой:

  0. python3 ftp_publish.py --record-base --dir $WORK/<slug> [те же --slug/--remote-dir/…]
     Записывает БАЗУ: sha256 живой версии каждого файла, который потом поедет на прод
     (~/.cache/seo-publish/base-manifest/<remote-path>.sha256). Делается ОДИН раз,
     в момент снятия среза прода, до правок.
  1. правки страницы …
  2. python3 ftp_publish.py --dir $WORK/<slug>
     Перед заливкой каждый файл заново качается с прода и его sha сверяется с базой.
     Расхождение = die «база устарела, пересобери дельту от свежей live-версии» -
     значит, между шагом 0 и заливкой прод правил кто-то ещё (параллельная сессия),
     и заливка среза затёрла бы чужую работу. Файл без записанной базы = тоже die.

Режимы (независимые, каждый идемпотентен):

  0. Запись базы CAS:
       python3 ftp_publish.py --record-base --dir $WORK/<slug> [--slug …] [--remote-dir …]
       python3 ftp_publish.py --record-base --url /guide-<slug>/ --url /blog/
     Ничего не заливает, только качает живые версии и пишет манифесты sha256.

  1. Деплой статьи:
       python3 ftp_publish.py --dir $WORK/<slug> [--slug <slug>] [--include-loose] [--dry-run]
     Каталог = index.html + assets/ с картинками статьи (канон путей: относительный
     `assets/<имя>.webp` на странице → /guide-<slug>/assets/<имя>.webp на проде).
     БЕЛЫЙ СПИСОК: на прод уезжают только index.html и картинки из assets/. Всё
     остальное в рабочем каталоге (рендеры QA, скрины живой страницы, бэкапы,
     черновики, скрипты) не заливается по умолчанию, независимо от имени. Шаги:
       бэкап живого состояния прода (страница существует → скачать в бэкап-каталог)
       → залить index.html + assets → проверить каждый URL curl 200
       → при провале откатить перезаписанные файлы из бэкапа.
     ПЛОСКАЯ страница (файл в корне сайта, картинки в общем /assets/<slug>/):
       python3 ftp_publish.py --dir <каталог> --remote-dir "" \
           --page <slug>.html --remote-page <slug>.html \
           --assets-remote assets/<slug>
     Именно из-за отсутствия этого режима волны ретрофита писали свои скрипты
     деплоя с голым os.listdir() без белого списка - и роняли служебные PNG на прод.

  2. Карточка в индекс гайдов:
       python3 ftp_publish.py --update-blog --url /guide-<slug>/ --card-title "..." \
           --card-desc "..." [--card-category "..."] [--card-minutes N] [--card-date "..."] \
           [--card-thumb /assets/thumbs/guide-<slug>-thumb.webp] [--section nachalo] [--dry-run]
     Скачивает СВЕЖИЙ blog.html с прода (протокол мержа против гонки параллельных сессий),
     добавляет/обновляет ровно одну карточку, проверяет что ЧУЖИЕ карточки целы
     (число карточек до/после отличается максимум на 1, чужие href нетронуты), заливает.
     РАЗМЕТКА КАТАЛОГА ОПОЗНАЁТСЯ АВТОМАТИЧЕСКИ (инструмент раздаётся, у чужого сайта
     каталог бывает любым): новая - секции <section class="cat-section" id="…"> со
     счётчиком <p class="cat-count">, видимым <ul class="cards"> и хвостом под
     <details>, карточки <li class="card-item">; старая - <ul class="divide-y divide-line">
     с <li class="py-7">. Ни один признак не найден - стоп без заливки.
     В новой разметке карточка встаёт В НАЧАЛО ВИДИМОГО списка секции, счётчик секции
     растёт на 1 с правильной формой слова, «Ещё N» под <details> не трогается.
     --card-thumb задан - карточка с превью, не задан - card--text без картинки.
     🔴 БАРЬЕР КАРТИНОК РАБОТАЕТ И ЗДЕСЬ (с этой редакции). Каталог - самая картиночная
     страница сайта, а раньше режим шёл мимо обоих рубежей и верифицировал только
     байты. Теперь: --card-thumb обязан начинаться со слэша (иначе нормализуется
     вслух: в карточке каталога относительный путь резолвится в /blog/<путь> и
     промахивается мимо файла) и обязан отдавать 2xx с прода - иначе стоп ДО сборки
     карточки; затем предполёт по смерженному каталогу и постфлайт по живому.
     Блокирует только то, что принесла ЭТА правка: чужое превью, сгнившее месяц
     назад, даёт громкое предупреждение, но публиковать новую карточку не мешает -
     иначе каталог нельзя было бы обновить до ручного ремонта старого.

  2а. Селфтест мержа каталога (офлайн, без сети/FTP/конфига):
       python3 ftp_publish.py --selftest-blog
     Синтетические мини-каталоги обеих разметок: вставка новой карточки, обновление
     существующей, счётчик секции, негативы (неопознанная разметка, нет секции,
     мержер снёс чужие карточки). Ненулевой exit при любом провале.

  3. RSS:
       python3 ftp_publish.py --update-rss --url <полный URL> --card-title "..." \
           --card-desc "..." [--pub-date "RFC822"] [--dry-run]
     Аналогично blog: свежий rss.xml с прода → добавить/обновить <item> (RSS 2.0,
     новые сверху, максимум 25 материалов) → чужие item целы → залить.

  4. Пинг индексации (ТОЛЬКО прямой IndexNow, БЕЗ heal_page/self-heal):
       python3 ftp_publish.py --ping --url <URL> [--url <URL> ...]

  5. Двуногая индексация (Яндекс + Google), код-гейт вместо прозы:
       python3 ftp_publish.py --index-legs --url <remote-path или URL> [--url ...]
     ГЕЙТ 0 (до обеих ног): HEAD-проверка каждого URL, не выше одного запроса
     одновременно с паузой между ними. Не 200 хотя бы у одного - НЕНУЛЕВОЙ exit
     поимённо, ни Яндекс, ни очередь GSC не трогаются - не гоним пинг битых URL.
     Нога Яндекс: прямой indexnow_ping() (тот же слой, что режим 4/--ping) - бьёт
     синхронно в yandex.com/indexnow и api.indexnow.org. Ни один из двух
     эндпоинтов не принял (не 200/202) - НЕНУЛЕВОЙ exit с текстом. Один из двух
     принял - WARN-строка в лог с деталями и exit 0 (частичный приём - не провал).
     Нога Google: у GSC нет публичного batch-submit URL без живой OAuth-сессии
     владельца, поэтому автоматически закрыть её отсюда нельзя. URL пишется в
     очередь .business/growth/seo/gsc-pending.json с датой постановки -
     отправка в GSC руками или агентом при живой сессии браузера, вычёркивание
     из очереди - его забота, не этого скрипта. Очередь GSC пишется независимо
     от исхода ноги Яндекс - работа не теряется, даже если Яндекс-нога упала.
     Вывод: "нога Яндекс: отправлено N / нога Google: в очереди M, старейшая
     неотправленная X дней".
     Гейт: если старейшая НЕОТПРАВЛЕННАЯ запись очереди Google (без sent_at)
     старше 7 дней - НЕНУЛЕВОЙ exit с текстом "Google-нога не закрывается,
     требуется сессия GSC" - код-гейт вместо забытой прозы в чате, очередь не
     даёт молча копиться бесконечно. Запись с проставленным sent_at (закрыта
     руками/агентом через живую сессию GSC либо ночным gsc_daily_reindex) в
     возраст НЕ идёт - иначе гейт бесконечно стареет по дате появления файла
     в очереди, а не по тому, что реально висит неотправленным (фикс r7,
     по решению автора: запись по решению автора без чистки навсегда оставалась «старейшей» и
     валила деплой при полностью здоровой очереди).
     Селфтест возраста очереди (офлайн, без сети): python3 ftp_publish.py
     --selftest-gsc-queue

ПРЕДПОЛЁТНЫЕ ГЕЙТЫ И РЕЖИМ strict_gates (фикс по решению автора, дефекты Б4 и В6).
Гоняются ПЕРВЫМИ в режиме --dir, до сети и до CAS: гейт артефактов (статья прошла
конвейер) и гейт дверей (байт-лок <title> страниц, на которые ведёт код-слово).
Раньше оба были fail-open: нет ключа в конфиге или нет файла по ключу - гейт молча
пропускался. На релее (боевая дверь при бане локального IP) каталог статьи ТОНКИЙ,
движка гейта там нет, и заливка шла вообще без проверок.

  strict_gates: true в ~/.config/seo-publish.json  - отсутствие движка гейта, ключа
    или файла канона = СТОП с понятной причиной (fail-closed). Ставится на машинах
    конвейера: и локально, и на релее.
  ключа нет (машина ученика, чужой проект) - прежний мягкий режим: чего нет, то
    пропускается со строкой в лог. Инструмент раздаётся, ломать чужие сборки нельзя.

СОСТАВ ГЕЙТОВ В РАСПИСКЕ gates.json (правка 22.08.2026). Б16 привязал расписку к
БАЙТАМ страницы, но не к составу проверок: волна добавляет в стадию page новый
гейт, а собранные раньше страницы едут в прод с зелёным вердиктом ПРОШЛОГО
набора - мимо него. Теперь запись стадии несёт `gate_set`, и дверь сверяет его с
эталоном, который отдаёт САМ раннер гейтов (`article_gates.py --gate-set page`);
второго списка имён гейтов здесь нет и быть не должно. Расписка без поля или с
другим составом = недействительна, и дверь сама зовёт перегон стадии page ОДИН
раз (миграция - работа машины, не человека). Автоперегон выключается флагом
--no-auto-regate, весь гейт целиком - только --unsafe-skip-artifacts.

БАРЬЕР ОБЛОЖЕК - два контура: (1) происхождение кадров, гейт frame-provenance
того же раннера (у хиро и og обязана быть запись в shots-manifest.json рядом со
страницей, классы result/step/own-run/inherited; по умолчанию ПРЕДУПРЕЖДЕНИЕ,
замок - флаг --provenance-hard); (2) фингерпринт генератора текст-карточек
cover-spec*.json рядом со страницей И в подпапках сборки первого уровня
(visual-src/ и соседи) - запрет владельца, СТОП.

РАСПИСКА ГЕЙТА gates-manifest.json - как гейт доезжает туда, где его нечем прогнать:
  · машина с каталогом конвейера: гейт прогнан → рядом со статьёй кладётся
    gates-manifest.json (стадия, вердикт, sha256 страницы, время, волна, агент);
  · staging везёт эту расписку на релей ВМЕСТЕ со страницей - у проекта это
    отдельный скрипт (в белый список заливки на прод файл не входит и туда не
    уезжает). Расписка и index.html обязаны ехать ОДНОЙ посылкой и совпадать по
    sha: пересобрал страницу - перемить расписку, иначе дверь встанет (Б7);
  · релей: движка гейта нет → расписка принимается как подтверждение, но только
    если её sha256 совпадает с ЗАЛИВАЕМЫМ index.html. Правка страницы после прогона
    гейта расписку обесценивает - при strict_gates это СТОП.
Селфтест обоих режимов: python3 ftp_publish.py --selftest-gates

БАРЬЕР КАРТИНОК - два рубежа против «файл залит, а на странице дыра» (по решению автора,
боевой дефект: битый hero на живой статье). Верификация деплоя проверяла ЗАЛИТЫЕ
ФАЙЛЫ, а браузер запрашивает то, что НАПИСАНО В HTML, и считает адрес
ОТНОСИТЕЛЬНО URL страницы. У плоской раскладки (страница отдаётся по /<путь>/, а
картинки лежат в общем корневом /assets/<имя>/) относительный `assets/<имя>/x`
резолвится в /<путь>/assets/<имя>/x = 404 при полностью зелёном деплое; внутри
<picture> промах <source srcset> НЕ откатывается на <img src>, поэтому картинки
нет вовсе. Рубежи:
  ПРЕДПОЛЁТ  - каждая ссылка страницы резолвится относительно КАЖДОГО адреса, по
    которому страница будет отдаваться (адрес заливки + canonical самой страницы),
    и обязана лечь либо на файл из НАБОРА ЗАЛИВКИ, либо на файл, уже живой на
    проде. Не сходится - отказ заливки с резолвом и готовой подсказкой «что
    написать вместо». Осознанный обход: --skip-image-health.
  ПОСТФЛАЙТ  - после совпадения байтов страница качается с прода, и HTTP каждой её
    ссылки на изображение проверяется живьём. Не-200 = провал деплоя с тем же
    откатом из бэкапа, что при расхождении байтов.
    🔴 ЗАКОН УЛИК ПОСТФЛАЙТА (по решению автора). Возврат постфлайта сносит УЖЕ ЗАЛИТУЮ и
    побайтово сверенную страницу, поэтому откат делается только по доказанному
    ответу сервера. Статус есть и он не 2xx/3xx - дефект. Транспорт промолчал
    (таймаут, обрыв) - два повтора с паузой, и если так и не ответило,
    предупреждение БЕЗ отката: «сеть моргнула» не равно «картинки нет». Сама
    страница не скачалась - повтор, затем попытка без кэш-бастера ?ihc= (его
    режут прокси и WAF), дальше тоже предупреждение. Пустой атрибут остаётся
    дефектом всегда: он виден в HTML и от сети не зависит. Подсказка «файл не
    залит или переименован» печатается ТОЛЬКО когда код ответа реально был -
    раньше она всплывала на обычном таймауте и отправляла чинить целый файл.
--skip-image-health снимает ОБА рубежа сразу: половинчатый обход залил бы страницу
и тут же откатил её, что хуже отсутствия обхода вовсе.
data:-URI, чужие домены (счётчики аналитики, CDN) и якоря барьер не валят.
Парсер и резолвер не дублируются - берутся из соседнего image_health.py.
🔴 ФАЙЛА РЯДОМ НЕТ (или он не грузится) = ОТКАЗ ПУБЛИКАЦИИ, а не предупреждение
(по решению автора, круг 4). Раньше это была мягкая деградация: ⚠️-строка в лог и код
возврата 0 - то есть барьер, который нечем проверить, засчитывался пройденным.
Ровно так он и оказался молча выключен на боевом релее, через который едет весь
корпус. Непроверенный барьер не равен пройденному ни на одной машине: отказ не
зависит от strict_gates, потому что image_health.py - не настраиваемый в конфиге
движок, а СОСЕДНИЙ ФАЙЛ той же поставки, и его отсутствие означает сломанную
раскладку инструмента, а не выбор оператора. Осознанный обход один и явный:
--skip-image-health (он громко пишет в лог, что барьер снят руками).
Селфтест барьера (офлайн): python3 ftp_publish.py --selftest-image-health
Он же - дешёвая проверка связности «жив ли барьер на этой машине»: без соседнего
image_health.py отдаёт rc=1, а не «пропущено, всё ок».

Все офлайн-наборы одной командой (гейты + мерж каталога + возраст очереди GSC +
барьер картинок):
    python3 ftp_publish.py --selftest

МИНТ РАСПИСКИ ОТДЕЛЬНЫМ РЕЖИМОМ (В17, фикс-6 по решению автора):
       python3 ftp_publish.py --mint-manifest <каталог статьи|песочница патча>
  Гоняет ровно ЛОКАЛЬНЫЕ гейты (артефакты + двери), пишет gates-manifest.json и
  отдаёт 0/1 ПО ГЕЙТАМ. Сеть, CAS и FTP не участвуют. Зачем отдельный режим:
  раньше расписку выписывал только `--dir … --dry-run`, который сразу после этого
  шёл в CAS за живым продом; при забаненном локальном IP прод недостижим, базы
  нет - и команда, вся задача которой «выписать расписку», отдавала rc=1 УЖЕ
  ПОСЛЕ записи расписки. Красный код толкал «починить» единственным быстрым
  способом - записать базу из локальной копии, то есть соврать про прод.
  Теперь враньё отбито кодом (см. --record-base ниже), а честный минт есть.

--record-base пишет базу ТОЛЬКО со свежего ЖИВОГО ответа прода. Прод не отвечает
  (или отдаёт заглушку вместо страницы) = отказ: базу «из локальной копии» не
  пишем никогда - она соврёт про состояние прода и снимет защиту от клоббера.
  Нет доступа к проду с этой машины - записывать базу оттуда, откуда он виден.

--dry-run: показать план/собрать результат локально, на FTP НИЧЕГО не заливать.
  Побочный эффект в режиме --dir: минт расписки гейтов (отдельный честный вход -
  --mint-manifest выше, ему CAS не мешает).
  Недоступность прода в этом режиме = ПРЕДУПРЕЖДЕНИЕ и rc 0 (В11): заливки нет,
  а сверять базу с недостижимой машины нечем по природе маршрута. Боевой режим
  без изменений: прод не отвечает = стоп. Расхождение и отсутствие базы CAS
  смертельны в обоих режимах - это локальные факты, сетью они не объясняются.
Коды выхода: 0 - успех; 1 - ошибка/откат (причина печатается).
"""
from __future__ import annotations

import argparse
import datetime
import hashlib
import inspect
import json
